@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage
@{
    var blog = Model.AncestorOrSelf<BlogFrontPage>();
    var title = blog is null || blog.Id == Model.Id ? Model.Name : $"{Model.Name} | {blog.Name}";
}
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@title</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</head>
<body class="flex min-h-screen flex-col bg-slate-50 text-slate-800 antialiased">
    <header class="sticky top-0 z-20 border-b border-slate-200 bg-white/85 backdrop-blur">
        <div class="mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
            <a href="@(blog?.Url() ?? "/")" class="flex items-center gap-2 text-lg font-bold tracking-tight text-slate-900">
                <span class="inline-block size-3 rotate-45 rounded-sm bg-indigo-600"></span>
                @(blog?.Name ?? Model.Name)
            </a>
            <a href="https://modelcontextprotocol.io" class="text-sm font-medium text-slate-600 hover:text-indigo-600">What is MCP?</a>
        </div>
    </header>

    <main class="flex-1">
        @RenderBody()
    </main>

    <footer class="border-t border-slate-200 bg-white">
        <div class="mx-auto max-w-6xl px-6 py-8 text-sm text-slate-500">
            Built with Umbraco through the Model Context Protocol. Photos from <a href="https://unsplash.com" class="underline hover:text-indigo-600">Unsplash</a>.
        </div>
    </footer>
</body>
</html>
