using Umbraco.Bench.Umbraco.Models;
using Umbraco.Bench.Umbraco.Models.Blog;
using Umbraco.Cms.Core.Models.PublishedContent;
using Umbraco.Extensions;

namespace Umbraco.Bench.Umbraco.Services;

// Finds the posts of the blog the current page belongs to, newest first.
public class BlogPostService
{
    public IReadOnlyList<BlogPostCardModel> GetLatestPosts(IPublishedContent currentPage, int maxItems)
    {
        var blog = currentPage.AncestorOrSelf<BlogFrontPage>();
        if (blog is null)
            return [];

        IEnumerable<BlogPost> posts = (blog.Children<BlogPost>() ?? [])
            .OrderByDescending(post => post.PublishDate);

        if (maxItems > 0)
            posts = posts.Take(maxItems);

        return posts
            .Select(post => new BlogPostCardModel
            {
                Title = post.Name,
                Url = post.Url(),
                Excerpt = post.Excerpt,
                ImageUrl = post.ListingImage?.GetCropUrl(width: 800, height: 450),
                ImageAlt = post.ListingImage?.Name ?? "",
                PublishDate = post.PublishDate,
            })
            .ToList();
    }
}
